// errors.ts — Constitution 5 §28–31, §221 (re-applied Oct 4 2026): the ONE registry of API error codes, shared by the
// server's exception filter and every app. Clients react to `error.code`, never to English text (§29): messages may
// change, codes do not. Each code carries its HTTP status, a SAFE default message (shown when the real message could
// leak internals — §31), its domain, whether retrying can help, severity, and the action an app should offer (§221).
// Today's routes still throw many older free-form codes; those keep working (the filter passes them through) and a
// ratchet gate (check:error-codes) stops NEW invented ones — add a code here instead.
/** §221: every action an app may be told to take — the one list (client normaliser, OpenAPI enum, registry entries). */
export const CLIENT_ACTIONS = ['RETRY', 'REAUTHENTICATE', 'REFRESH', 'CONTACT_MANAGER', 'UPGRADE_PLAN', 'NONE'] as const;
export type ClientAction = typeof CLIENT_ACTIONS[number];
export const isClientAction = (a: unknown): a is ClientAction => typeof a === 'string' && (CLIENT_ACTIONS as readonly string[]).includes(a);
export interface ErrorDefinition { status: number; message: string; domain: string; retryable: boolean; severity: 'info' | 'warning' | 'error'; action: ClientAction }

